-  }
-  const n = $("#eylem-notu");
-  if (!n) return;
-  n.textContent = metin || "";
-  n.title = metin || "";
-  n.className = "eylem-notu" + (tur ? " " + tur : "");
-  clearTimeout(bildir._z);
-  bildir._z = setTimeout(() => { n.textContent = ""; n.className = "eylem-notu"; },
-                         tur === "kotu" ? 20000 : 12000);
