-  await devralAl();
-  D.ofis  = await al("/api/ofis");
-  D.tahta = await al("/api/tahta" + (D.kanat ? "?kanat=" + D.kanat : ""));
-  cizSerit(); cizGorunum(); cizBekleyenler(); cizSekme(); cizBaglam();
-  cizKullanim();
-  cizKod();
-}
-
-/* ─────────────── üst şerit ─────────────── */
-
-function cizSerit() {
