+      .sort(function (a, b) { return b.toplam - a.toplam || a.kategori.localeCompare(b.kategori, ''tr''); });
+  }
+
+  // Butce girdisi: bos -> null (butce yok), gecersiz ya da negatif -> NaN, aksi halde sayi (''1250,50'' -> 1250.5)
