+        alaniBitir(); satirlar.push(satir); satir = [];
+      } else { bos += c; gorunen = true; }
+    }
+    if (bos !== '''' || satir.length || gorunen) { alaniBitir(); satirlar.push(satir); }
+    return satirlar.filter(function (s) { return !(s.length === 1 && s[0] === ''''); });
