 .hata { color: #b91c1c; margin: 0; grid-column: 1 / -1; min-height: 1em; }
 .bos { color: #6b7280; }
 @media (max-width: 560px) { form { grid-template-columns: 1fr; } }
+.butce-form { grid-template-columns: 2fr 2fr auto; align-items: end; }
