INSERT INTO "kanit" VALUES('e00132663e7540d7ad8319b7e90acc8a','5559a0b7c9584640b6d51155348d0c93','terminal','Eski #5 davranışı geri gelince sınama ateş ediyor','Komut: python .ofis/karalama/baris_kart_regresyon.py
