INSERT INTO "olay" VALUES(7039,'915d303e41ee4cb59fa908401d277926','asli','70e209ff5e464d9cadcba2e47a6fc628','cikti','Sınama koşusu yine kapıda durdu, bu yüzden sınama sonucu henüz yok.

